bashdown.source:
--[[	Bashdown (active)

	melee forward and downward attack
	Affects 1 target
	
	Mana Cost: 5			|	+1 mana cost
	Cast time: 0,5 sec	|
	Cooldown: none			|

	Min Bonus Dam +2		|	Min Bonus Dam +2
	Max Bonus Dam +5		|	Max Bonus Dam +5

--]]


-- ----------------------------------------------------------------------------------------------
-- DATA
-- ----------------------------------------------------------------------------------------------
-- Constants
local RANGE				= 160.0;

local CLASS_ID			= GetPyOID("ClassTable", "Skill_Warrior_BashDown");

-- Cached values
local skill_level	= 0;
local mana_cost;
local target;
local traces 		= false;


-- ----------------------------------------------------------------------------------------------
-- CALLBACKS
-- ----------------------------------------------------------------------------------------------
-- ----------------------------------------------------------------------------------------------
local function OnSkillInfo_(slvl)
	SetTempProps(CLASS_ID, slvl);
end

-- ----------------------------------------------------------------------------------------------
local function OnSkillUpdate_()
	local slvl = GetCurrentSkillInfo();
	SetProp(GetPyStruct("CharacterProperties", "SnS_Level"), ToFixed(skill_level));
	if(slvl ~= skill_level) then
		skill_level	= slvl;
	end
	mana_cost	= CalcManaCost(CLASS_ID, slvl);
end

-- ----------------------------------------------------------------------------------------------
local function OnSkillCheck_()
	return HasMana(mana_cost), false;
end

-- ----------------------------------------------------------------------------------------------
local function OnPreSkill_()
	-- We only target enemies
	SetTargetListCharacterFilter(GetPyCst("AITargetList_CharacterFilter", "Enemy"));
	-- We only target destructible objects
	SetTargetListObjectFilter(GetPyCst("AITargetList_ObjectFilter", "AttackableOnly"));
	-- Look for target in front of us prior to looking for the distance
	SetTargetListSorting(GetPyCst("AITargetList_Sorting", "FrontalFirst"));

	TargetListSearch(RANGE);

	if(not IsTargetListEmpty()) then
		target = GetTargetListTop();
		LookAt(target);
	else
		target = nil;
	end

	if (traces) then Trace("[Skills | Bashdown] consumes "..FromFixed(mana_cost).." mana..."); end
	UseMana(mana_cost);
	--The effect animation is in animation.pyarray
	--PlayFX(GetPyOID("AnimatedEffectTable", "skill_dh2_prince_warrior_bash_down"));
end

-- ----------------------------------------------------------------------------------------------
local function OnSkill_()
	if(target) then
		-- Because OnSkill() is only called once for Instant skill type, we can ApplyPropClass() here
		SetProp(GetPyStruct("CharacterProperties", "SnS_Level"), ToFixed(skill_level));
		ApplyPropClass(CLASS_ID);

		local dmg = SkillCombatRoll(target);
	end
end

-- ----------------------------------------------------------------------------------------------
local function OnPostSkill_()
	ClearTarget();
end

-- ----------------------------------------------------------------------------------------------
RegisterSkill(OnSkillUpdate_, OnSkillCheck_, OnPreSkill_, OnSkill_, OnPostSkill_, nil, OnSkillInfo_);

charge.source:
--[[	Charge (Active)

	A charging attack against the nearest opponent (or in the direction the 
	player is facing) which push all enemies caught in his path backwards. 
	This attack deals melee damage based on the warrior level, the charge skill 
	level and his endurance and strength stats. The warrior also gains bonus to 
	damage for this skill if he has a shield equipped.
	
		Mana Cost: 7			|	+1 mana cost
		Cast time: 0,5 sec	|
		Cooldown: 1 sec		|
									|
		Distance: 200			|	+20 distance (same duration)
		Shield Bonus:			|	Shield Bonus:
  			Min Bonus Dam +2	|		Min Bonus Dam +2
  			Max Bonus Dam +5	|		Max Bonus Dam +5
  			
  			20 may 2010,	Script is almost working 100%. Need only to have the base 
  								values set in the character class table
	
			26 may 2010, 	Found the way to set the values for the skill from the character class table.

--]]


-- ----------------------------------------------------------------------------------------------
-- DATA
-- ----------------------------------------------------------------------------------------------
-- Constants

local RANGE			= 300.0; --Basic range of the skill
local ANGLE			= 120.0; --90 deg was too small for all ennemies near the player. 180 should cover everybody in front.

local CLASS_ID				= GetPyOID("ClassTable", "Skill_Warrior_Charge");
local CLASS_ID_SHIELD	= GetPyOID("ClassTable", "Skill_Warrior_Charge_ShieldBonus");

local USE_COOLDOWN	= true;

-- Cached values
local skill_level		= 0;
local mana_cost;
local cooldown;
local traces			= false;


-- ----------------------------------------------------------------------------------------------
-- CALLBACKS
-- ----------------------------------------------------------------------------------------------
-- ----------------------------------------------------------------------------------------------
local function OnSkillInfo_(slvl)
	if (HasShield()) then
		SetTempProps(CLASS_ID_SHIELD, slvl);
	else
		SetTempProps(CLASS_ID, slvl);
	end
	return cooldown;
end
-- ----------------------------------------------------------------------------------------------
local function OnSkillUpdate_()
	local slvl = GetCurrentSkillInfo();
	
	if(slvl ~= skill_level) then
		skill_level	= slvl;
	end
	SetProp(GetPyStruct("CharacterProperties", "SnS_Level"), ToFixed(skill_level));
	mana_cost	= CalcManaCost(CLASS_ID, slvl);
	cooldown = FromFixed(GetProp(GetPyStruct("CharacterProperties", "SnS_Cooldown"), true));
	if(cooldown < 0) then cooldown = 0; end
end

-- ----------------------------------------------------------------------------------------------
local function OnSkillCheck_()
	return (not HasSkillCooldown() and HasMana(mana_cost)), false;
end

-- ----------------------------------------------------------------------------------------------
local function OnPreSkill_()
	SetTargetListCharacterFilter(GetPyCst("AITargetList_CharacterFilter", "Enemy"));
	SetTargetListObjectFilter(GetPyCst("AITargetList_ObjectFilter", "AttackableOnly"));
	SetTargetListSorting(GetPyCst("AITargetList_Sorting", "FrontalFirst"));

	TargetListSearch(RANGE);

	if(not IsTargetListEmpty()) then
		LookAt(GetTargetListTop());
	end

	UseMana(mana_cost);
	SetSkillCooldown(cooldown);
end

-- ----------------------------------------------------------------------------------------------
local function OnSkill_()
	SetTargetListSorting(GetPyCst("AITargetList_Sorting", "NoSort"));
	TargetListSearch(RANGE, ANGLE);
	
	-- Extra damage if the player is equipped with a shield
	if (HasShield()) then
		ApplyPropClass(CLASS_ID_SHIELD);
	else
		ApplyPropClass(CLASS_ID);
	end
	
	if(not IsTargetListEmpty()) then
		repeat
			local target = GetTargetListTop();
			SkillCombatRoll(target);
			PopTargetList();
		until(IsTargetListEmpty())
	end
end

-- ----------------------------------------------------------------------------------------------
local function OnPostSkill_()
  if (not TargetInMeleeRange()) then
	 ClearTarget();
	end 
end

-- ----------------------------------------------------------------------------------------------
RegisterSkill(OnSkillUpdate_, OnSkillCheck_, OnPreSkill_, OnSkill_, OnPostSkill_, nil, OnSkillInfo_);

ground_slam.source:
--[[	Ground Slam (Active)

	Warrior perform a hit on the ground that create a shockwave
	high chance to knockback enemies
		Mana Cost: 10					|	+1 mana cost

		Cast time: 1 sec				|
		Cooldown: 2 sec				|

		Shockwave radius: 300		|	+5% Shockwave radius
		20 may 2010, almost 100% working
		24 may 2010, 	was able to incorportate the data from the character class table
							now the range, and cooldown are taken from it.
--]]


-- ----------------------------------------------------------------------------------------------
-- DATA
-- ----------------------------------------------------------------------------------------------
-- Constants

local RANGE						= 300.0;
local F_RANGE					= 0.0;
local ForcedKnockback			= 120.0;

local CLASS_ID					= GetPyOID("ClassTable", "Skill_Warrior_GroundSlam");
local USE_COOLDOWN				= true;

-- Cached values
local skill_level				= 0;
local mana_cost;
local cooldown;
local traces					= false;


-- ----------------------------------------------------------------------------------------------
-- CALLBACKS
-- ----------------------------------------------------------------------------------------------
local function OnSkillInfo_(slvl)
	SetTempProps(CLASS_ID, slvl);
	return cooldown;
end

local function OnSkillUpdate_()
	local slvl = GetCurrentSkillInfo();
	if(slvl ~= skill_level) then
		skill_level	= slvl;
	end
	
	SetProp(GetPyStruct("CharacterProperties", "SnS_Level"), ToFixed(skill_level));
	
	mana_cost	= CalcManaCost(CLASS_ID, skill_level);
	RANGE 		= FromFixed(GetProp(GetPyStruct("CharacterProperties", "TempProp1"), true));
	cooldown 	= FromFixed(GetProp(GetPyStruct("CharacterProperties", "SnS_Cooldown"), true));
	
	-- 5% increase of the range per skill level
	local RANGE2 = FromFixed(GetProp(GetPyStruct("CharacterProperties", "TempProp2"), true));
	F_RANGE = RANGE + ((RANGE * RANGE2/100)* skill_level);
	if(cooldown < 0) then cooldown = 0; end
end

-- ----------------------------------------------------------------------------------------------
local function OnSkillCheck_()
	return (not HasSkillCooldown() and HasMana(mana_cost)), false;
end

-- ----------------------------------------------------------------------------------------------
local function OnPreSkill_()
	if (traces) then Trace("[Skills | Ground Slam] consumes "..FromFixed(mana_cost).." mana..."); end
	UseMana(mana_cost);
	SetSkillCooldown(cooldown);
end

-- ----------------------------------------------------------------------------------------------
local function OnSkill_()
   	local hasLookedAtTarget = false;
	
	SetTargetListCharacterFilter(GetPyCst("AITargetList_CharacterFilter", "Enemy"));
	SetTargetListObjectFilter(GetPyCst("AITargetList_ObjectFilter", "AttackableOnly"));
	SetTargetListSorting(GetPyCst("AITargetList_Sorting", "ClosestFirst"));
	TargetListSearch(RANGE);
	
	SetProp(GetPyStruct("CharacterProperties", "SnS_Level"), ToFixed(skill_level));
	ApplyPropClass(CLASS_ID);
	
  	if(not IsTargetListEmpty()) then
		repeat
			local target = GetTargetListTop();
			if (not hasLookedAtTarget) then
				LookAt(target);
				hasLookedAtTarget = true;
			end
			PopTargetList();
			SkillCombatRoll(target);
		until(IsTargetListEmpty())
	end
end

-- ----------------------------------------------------------------------------------------------
local function OnPostSkill_()
	ClearTarget();
end

-- ----------------------------------------------------------------------------------------------
RegisterSkill(OnSkillUpdate_, OnSkillCheck_, OnPreSkill_, OnSkill_, OnPostSkill_, nil, OnSkillInfo_);
